/* ═══ PROCESSING METHODS (17+) ═══ */
export const PROCESSING_METHODS: ProcessingMethod[] = [
  { id: "washed", name: "Washed (Wet Process)", category: "classic", description: "Cherry skin and mucilage removed before drying. The bean ferments in water tanks to dissolve remaining fruit. Produces the cleanest, most terroir-transparent cups.", flavorImpact: "Clean, bright acidity, clear origin character. What you taste is the bean, not the process.", complexity: 3 },
  { id: "natural", name: "Natural (Dry Process)", category: "classic", description: "Whole cherries dried on raised beds with fruit intact. The bean absorbs sugars and flavors from the drying fruit. The oldest processing method — predates washed by centuries.", flavorImpact: "Fruity, sweet, heavy body, wine-like. The fruit speaks as loudly as the bean.", complexity: 4 },
  { id: "honey", name: "Honey Process", category: "classic", description: "Cherry skin removed but some or all mucilage left on during drying. Named for the sticky, honey-like texture of the drying beans. Bridges washed clarity and natural fruitiness.", flavorImpact: "Sweet, medium body, stone fruit. The Goldilocks of processing.", complexity: 5 },
  { id: "red-honey", name: "Red Honey", category: "classic", description: "More mucilage left on than yellow honey, less than black honey. Dried more slowly for deeper fruit absorption.", flavorImpact: "Sweeter than yellow honey, more fruit depth, maple-like sweetness.", complexity: 6 },
  { id: "black-honey", name: "Black Honey", category: "classic", description: "Nearly all mucilage left on. Dried very slowly, often covered. Maximum fruit absorption short of natural process.", flavorImpact: "Very sweet, heavy body, dried fruit, almost natural-like.", complexity: 7 },
  { id: "wet-hulled", name: "Wet-Hulled (Giling Basah)", category: "classic", description: "Unique to Indonesia. Parchment removed while beans are still wet (30-35% moisture vs. 11% for other methods). Creates the distinctive earthy, herbal Sumatran profile.", flavorImpact: "Earthy, herbal, heavy body, low acidity, tobacco, cedar. Polarizing and unique.", complexity: 5, controversy: "Some argue it's a defect. Others call it terroir. The debate is the point." },
  { id: "anaerobic-natural", name: "Anaerobic Natural", category: "experimental", description: "Whole cherries sealed in oxygen-free tanks before natural drying. Controlled fermentation creates intense, sometimes wine-like flavors.", flavorImpact: "Intensely fruity, wine-like, tropical, sometimes boozy. Fermentation amplified.", complexity: 8 },
  { id: "anaerobic-washed", name: "Anaerobic Washed", category: "experimental", description: "Depulped beans fermented in sealed, oxygen-free tanks before washing. More controlled than natural anaerobic.", flavorImpact: "Clean but intensified — brighter acidity with unexpected fruit notes.", complexity: 8 },
  { id: "lactic-anaerobic", name: "Lactic Anaerobic", category: "experimental", description: "Anaerobic fermentation with lactic acid bacteria inoculation. Creates creamy, yogurt-like qualities.", flavorImpact: "Creamy, lactic, smooth body, stone fruit, sometimes cider-like.", complexity: 9 },
  { id: "carbonic-maceration", name: "Carbonic Maceration", category: "experimental", description: "Borrowed from wine. Whole cherries in CO2-flushed tanks. Intracellular fermentation creates unique flavor compounds.", flavorImpact: "Candy-like sweetness, tropical fruit, bubblegum, sometimes cinnamon.", complexity: 9, controversy: "Critics say it masks terroir. Fans say it reveals new dimensions. Both are right." },
  { id: "thermal-shock", name: "Thermal Shock", category: "experimental", description: "Alternating hot and cold water during fermentation. Rapid temperature changes create unique chemical reactions.", flavorImpact: "Intense, complex, sometimes tropical or floral notes not found in traditional processing.", complexity: 10, controversy: "The newest frontier. Results are inconsistent but when it works, it's transcendent." },
  { id: "koji-fermentation", name: "Koji Fermentation", category: "experimental", description: "Aspergillus oryzae (koji mold, used in sake/miso) applied during fermentation. Creates umami and unique enzymatic breakdown.", flavorImpact: "Umami, savory-sweet, sake-like, completely unique. The weirdest coffee you'll ever taste.", complexity: 10, controversy: "Is it still coffee? Purists say no. Innovators say it's the future." },
  { id: "swiss-water-decaf", name: "Swiss Water Decaf", category: "decaf", description: "Chemical-free decaffeination using water and osmosis. Green beans soaked in water saturated with coffee solubles (minus caffeine). The gold standard for decaf.", flavorImpact: "Retains most origin character. Slight muting of acidity and complexity vs. caffeinated.", complexity: 3 },
  { id: "ea-decaf", name: "EA (Sugarcane) Decaf", category: "decaf", description: "Ethyl acetate derived from sugarcane dissolves caffeine. Common in Colombian decafs. Adds slight sweetness.", flavorImpact: "Sweet, slightly muted, retains body well. The tastiest decaf method.", complexity: 3 },
  { id: "co2-decaf", name: "CO2 Decaf", category: "decaf", description: "Supercritical CO2 selectively extracts caffeine. Most expensive but best flavor retention.", flavorImpact: "Closest to original flavor. Minimal impact on acidity and complexity.", complexity: 4 },
  { id: "extended-fermentation", name: "Extended Fermentation", category: "experimental", description: "Standard washed or natural process with fermentation times extended to 72-120+ hours. Longer contact develops more complex flavors.", flavorImpact: "Intensified sweetness, wine-like qualities, sometimes funky or boozy.", complexity: 7 },
  { id: "double-washed", name: "Double Washed", category: "classic", description: "Two rounds of washing and fermentation. Extra clean cup with maximum clarity.", flavorImpact: "Ultra-clean, bright, transparent. The purist's choice.", complexity: 4 },
];

