/* ═══ GLOSSARY (30+ terms) ═══ */
export const GLOSSARY: GlossaryTerm[] = [
  { id: "g1", term: "Cupping Score", category: "Quality", definition: "A standardized 100-point scale used by the Specialty Coffee Association (SCA) to evaluate coffee quality. Coffees scoring 80+ are considered 'specialty grade.'", whyItMatters: "It's the closest thing coffee has to an objective quality measure. But it's not gospel — great coffees can score 86 and boring coffees can score 90." },
  { id: "g2", term: "Q Grader", category: "Quality", definition: "A certified coffee taster who has passed the Coffee Quality Institute's rigorous 20-test exam. The sommelier equivalent for coffee.", whyItMatters: "Q Graders provide the cupping scores that drive pricing and reputation. There are fewer than 10,000 worldwide." },
  { id: "g3", term: "C-Market Price", category: "Economics", definition: "The commodity futures price for Arabica coffee on the Intercontinental Exchange (ICE). Currently around $1.80-2.50/lb for green coffee.", whyItMatters: "This is the baseline price farmers receive. Specialty premiums are measured as multiples above C-market. A farmer getting 3x C-market is doing well." },
  { id: "g4", term: "QPR (Quality-Price Ratio)", category: "Scoring", definition: "Our proprietary score measuring cup quality relative to price. A $15 coffee scoring 88 has better QPR than a $120 coffee scoring 94.", whyItMatters: "Because the best coffee isn't always the most expensive. QPR finds the sweet spot." },
  { id: "g5", term: "Terroir", category: "Origin", definition: "The complete natural environment in which coffee is grown — soil, altitude, climate, rainfall, shade. Borrowed from wine.", whyItMatters: "Terroir is why a Gesha from Panama tastes different from a Gesha from Ethiopia, even though it's the same variety." },
  { id: "g6", term: "Microlot", category: "Sourcing", definition: "A small, separately processed lot from a specific section of a farm. Usually under 100kg of green coffee.", whyItMatters: "Microlots allow farmers to showcase their best work and command premium prices. They're the single-vineyard wines of coffee." },
  { id: "g7", term: "Direct Trade", category: "Sourcing", definition: "Roasters buying directly from farmers, bypassing traditional importers. No formal certification — it's a relationship, not a label.", whyItMatters: "Direct trade can mean higher farmer payments and better quality. But without standards, it can also be marketing fluff." },
  { id: "g8", term: "Third Wave", category: "Culture", definition: "The movement treating coffee as an artisanal food rather than a commodity. First wave = mass market. Second wave = Starbucks. Third wave = specialty.", whyItMatters: "We're arguably in the fourth wave now — where science, fermentation, and data meet craft." },
  { id: "g9", term: "Extraction", category: "Brewing", definition: "The percentage of coffee solubles dissolved into water during brewing. Ideal range: 18-22%. Under-extracted = sour. Over-extracted = bitter.", whyItMatters: "Extraction is the single most important variable in brewing. Get it right and any decent coffee tastes great." },
  { id: "g10", term: "TDS (Total Dissolved Solids)", category: "Brewing", definition: "The concentration of coffee solubles in your cup, measured with a refractometer. Typical range: 1.15-1.45%.", whyItMatters: "TDS tells you how strong your coffee is. Combined with extraction yield, it maps the entire flavor space." },
  { id: "g11", term: "Degassing", category: "Freshness", definition: "CO2 released from roasted coffee over days/weeks. Fresh coffee needs 3-7 days of degassing before optimal brewing.", whyItMatters: "Too fresh = CO2 interferes with extraction. Too old = stale. The sweet spot is 7-21 days post-roast." },
  { id: "g12", term: "Mycotoxin", category: "Health", definition: "Toxic compounds produced by mold (Aspergillus, Ochratoxin A). Present in some coffee at trace levels. The basis of Bulletproof's marketing.", whyItMatters: "Levels in commercial coffee are well below safety thresholds. The fear is mostly marketing, but testing is still good practice." },
  { id: "g13", term: "Cherry", category: "Botany", definition: "The fruit of the coffee plant. Each cherry typically contains two seeds (beans). The variety, ripeness, and processing of the cherry determine cup quality.", whyItMatters: "Coffee is a fruit. Understanding the cherry is understanding the entire flavor chain." },
  { id: "g14", term: "Parchment", category: "Processing", definition: "The papery layer surrounding the coffee bean inside the cherry. Removed during milling (hulling) before export.", whyItMatters: "Parchment protects the bean during drying and storage. Wet-hulled coffee removes it early, which is why Sumatran coffee tastes different." },
  { id: "g15", term: "Green Coffee", category: "Trade", definition: "Unroasted coffee beans after processing and milling. This is what roasters buy from importers or directly from farms.", whyItMatters: "Green coffee is shelf-stable for 6-12 months. Roasted coffee starts degrading in days. The supply chain runs on green." },
];

